<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content,variants=['a','b','c'];let state=null;
async function api(method='GET',body=null){const options={method,headers:{Accept:'application/json'}};if(body){options.headers['Content-Type']='application/json';options.headers['X-CSRF-Token']=csrf;options.body=JSON.stringify(body)}const response=await fetch('transfer-vote-20-09.php',options);const data=await response.json().catch(()=>({error:'Ungültige Serverantwort'}));if(!response.ok)throw new Error(data.error||'Speichern fehlgeschlagen');return data}
function esc(value){return String(value??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function stars(rating,variant){let html='<div class="stars">';for(let i=1;i<=5;i++)html+=`<button type="button" class="star-button ${i<=(rating||0)?'active':''}" data-rate="${i}" data-variant="${variant}" aria-label="${i} Sterne">★</button>`;return html+'</div>'}
function renderRatings(variant,view){document.getElementById('ratings-'+variant).innerHTML=Object.entries(view.profiles).map(([id,p])=>`<div class="person-rating"><b>${esc(p.name)}</b>${id===view.currentProfile?stars(view.ratings[id]||0,variant):`<span>${'★'.repeat(view.ratings[id]||0)}${'☆'.repeat(5-(view.ratings[id]||0))}</span>`}</div>`).join('')}
function dateText(iso){try{return new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(iso))}catch{return''}}
function commentHtml(c,view,reply){const deleted=!!c.deleted,name=deleted?'Gelöschter Kommentar':(view.profiles[c.profile]?.name||'Unbekannt'),canDelete=!deleted&&c.profile===view.currentProfile,replyAction=!reply&&!deleted?`<button type="button" data-reply="${esc(c.id)}">Antworten</button>`:'',deleteAction=canDelete?`<button type="button" data-delete="${esc(c.id)}">Löschen</button>`:'',replyForm=!reply&&!deleted?`<form class="reply-form" data-parent="${esc(c.id)}" data-variant="${esc(view.variant)}"><input maxlength="1000" placeholder="Antwort schreiben …" required><button>Antworten</button></form>`:'';return`<div class="comment ${reply?'reply':''}"><div class="comment-head"><strong>${esc(name)}</strong><span>${esc(dateText(c.createdAt))}</span></div><p>${deleted?'Kommentar wurde gelöscht.':esc(c.text)}</p><div class="comment-actions">${replyAction}${deleteAction}</div>${replyForm}</div>`}
function renderComments(variant,view){const host=document.getElementById('comments-'+variant),roots=view.comments.filter(c=>!c.parentId);host.innerHTML=roots.length?roots.map(root=>commentHtml(root,view,false)+view.comments.filter(c=>c.parentId===root.id).map(r=>commentHtml(r,view,true)).join('')).join(''):'<div class="rating-help">Noch keine Kommentare.</div>'}
function render(){variants.forEach(v=>{const view=state.variants[v];view.variant=v;renderRatings(v,view);renderComments(v,view);document.getElementById('avg-'+v).textContent=view.average===null?'–':`${view.average.toFixed(1)} / 5 (${view.ratingCount})`});const available=variants.filter(v=>state.variants[v].average!==null);if(available.length<variants.length){document.getElementById('leader').textContent='noch offen';return}const max=Math.max(...available.map(v=>state.variants[v].average)),winners=available.filter(v=>state.variants[v].average===max);document.getElementById('leader').textContent=winners.length===1?({a:'A · Direkt & entspannt',b:'B · Pointe-du-Lac',c:'C · Trois-Rivières'}[winners[0]]):'Gleichstand'}
document.addEventListener('click',async e=>{const rate=e.target.closest('[data-rate]');if(rate){const v=rate.dataset.variant,status=document.getElementById('status-'+v);try{status.textContent='Speichere …';state=await api('POST',{action:'rating',variant:v,rating:Number(rate.dataset.rate)});render();status.textContent='Bewertung gespeichert.'}catch(err){status.textContent=err.message}return}const reply=e.target.closest('[data-reply]');if(reply){const form=document.querySelector(`.reply-form[data-parent="${CSS.escape(reply.dataset.reply)}"]`);if(form){form.classList.toggle('open');if(form.classList.contains('open'))form.querySelector('input').focus()}return}const del=e.target.closest('[data-delete]');if(del){if(!confirm('Eigenen Kommentar wirklich löschen?'))return;const v=del.closest('.vcard').dataset.variant,status=document.getElementById('status-'+v);try{state=await api('POST',{action:'delete-comment',variant:v,commentId:del.dataset.delete});render();status.textContent='Kommentar gelöscht.'}catch(err){status.textContent=err.message}}});
document.addEventListener('submit',async e=>{if(e.target.matches('.comment-form,.reply-form')){e.preventDefault();const v=e.target.dataset.variant,input=e.target.querySelector('input'),status=document.getElementById('status-'+v),body={action:'comment',variant:v,text:input.value};if(e.target.dataset.parent)body.parentId=e.target.dataset.parent;try{status.textContent='Speichere …';state=await api('POST',body);input.value='';render();status.textContent=e.target.dataset.parent?'Antwort gespeichert.':'Kommentar gespeichert.'}catch(err){status.textContent=err.message}}});
api().then(data=>{state=data;render()}).catch(err=>variants.forEach(v=>document.getElementById('status-'+v).textContent='Abstimmung konnte nicht geladen werden: '+err.message));
</script>
</body>
